s://mapa-turystyczna.pl/route/iv1r","elevation_gain_verified_at":"2026-11-24T00:00:00Z","time_source_url":"https://mapa-turystyczna.pl/route/iv1r","time_verified_at":"2026-11-24T00:00:00Z","i18n":{"pl":{"name":"Wysoki Kamie\u0144: czerwonym ze Szklarskiej Por\u0119by","description":"Ze stacji Szklarska Por\u0119ba G\u00f3rna przez osiedle Podg\u00f3rze i Rozdro\u017ce pod Wysokim Kamieniem do punktu szlakowego Wysoki Kamie\u0144. Czerwony szlak, ko\u0144cowo wsp\u00f3lny z \u017c\u00f3\u0142tym. 3,2 km, 413 m podej\u015b\u0107 i 1 godz. 31 min dotycz\u0105 wej\u015bcia; powr\u00f3t jest poza zakresem.","notes":"Pocz\u0105tek \u015bladu jest przy stacji, a nie w dowolnym punkcie miasta. Nie dodano odcinka do pinezki szczytu. Przed wyj\u015bciem sprawd\u017a pogod\u0119 i komunikaty o pracach le\u015bnych; GPX nie potwierdza otwarcia ani bezpiecze\u0144stwa."},"en":{"name":"Wysoki Kamie\u0144: red trail from Szklarska Por\u0119ba","description":"From Szklarska Por\u0119ba G\u00f3rna station via the Podg\u00f3rze estate and Rozdro\u017ce pod Wysokim Kamieniem to the Wysoki Kamie\u0144 trail point. Follow red markings, shared with yellow at the end. The 3.2 km, 413 m ascent and 1 h 31 min exclude the return.","notes":"The track starts at the station, not at an arbitrary point in town. No connector to the peak pin is added. Check weather and forestry notices before setting off; GPX does not confirm access or safety."},"ua":{"name":"Wysoki Kamie\u0144: \u0447\u0435\u0440\u0432\u043e\u043d\u0438\u043c \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u043c \u0437\u0456 Szklarska Por\u0119ba","description":"\u0412\u0456\u0434 \u0441\u0442\u0430\u043d\u0446\u0456\u0457 Szklarska Por\u0119ba G\u00f3rna \u0447\u0435\u0440\u0435\u0437 \u0440\u0430\u0439\u043e\u043d Podg\u00f3rze \u0442\u0430 Rozdro\u017ce pod Wysokim Kamieniem \u0434\u043e \u0442\u043e\u0447\u043a\u0438 Wysoki Kamie\u0144 \u043d\u0430 \u0441\u0442\u0435\u0436\u0446\u0456. \u0427\u0435\u0440\u0432\u043e\u043d\u0435 \u043c\u0430\u0440\u043a\u0443\u0432\u0430\u043d\u043d\u044f, \u043d\u0430\u043f\u0440\u0438\u043a\u0456\u043d\u0446\u0456 \u0441\u043f\u0456\u043b\u044c\u043d\u0435 \u0437 \u0436\u043e\u0432\u0442\u0438\u043c. 3,2 \u043a\u043c, 413 \u043c \u043d\u0430\u0431\u043e\u0440\u0443 \u0432\u0438\u0441\u043e\u0442\u0438 \u0442\u0430 1 \u0433\u043e\u0434 31 \u0445\u0432 \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u044c \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f.","notes":"\u0422\u0440\u0435\u043a \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u044c\u0441\u044f \u0431\u0456\u043b\u044f \u0441\u0442\u0430\u043d\u0446\u0456\u0457, \u0430 \u043d\u0435 \u0432 \u0434\u043e\u0432\u0456\u043b\u044c\u043d\u0456\u0439 \u0442\u043e\u0447\u0446\u0456 \u043c\u0456\u0441\u0442\u0430. \u0417\u2019\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0437 \u043f\u043e\u0437\u043d\u0430\u0447\u043a\u043e\u044e \u0432\u0435\u0440\u0448\u0438\u043d\u0438 \u043d\u0435 \u0434\u043e\u0434\u0430\u043d\u043e. \u041f\u0435\u0440\u0435\u0434 \u0432\u0438\u0445\u043e\u0434\u043e\u043c \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0433\u043e\u0434\u0443 \u0439 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u043f\u0440\u043e \u043b\u0456\u0441\u043e\u0432\u0456 \u0440\u043e\u0431\u043e\u0442\u0438; GPX \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0434\u043e\u0441\u0442\u0443\u043f\u0443 \u0447\u0438 \u0431\u0435\u0437\u043f\u0435\u043a\u0438."},"zh":{"name":"Wysoki Kamie\u0144\uff1a\u4eceSzklarska Por\u0119ba\u6cbf\u7ea2\u8272\u6b65\u9053\u4e0a\u5c71","description":"\u4eceSzklarska Por\u0119ba G\u00f3rna\u8f66\u7ad9\u7ecfPodg\u00f3rze\u5c45\u6c11\u533a\u53caRozdro\u017ce pod Wysokim Kamieniem\u524d\u5f80Wysoki Kamie\u0144\u6b65\u9053\u70b9\u3002\u6cbf\u7ea2\u8272\u6807\u8bb0\u884c\u8d70\uff0c\u672b\u6bb5\u4e0e\u9ec4\u8272\u6b65\u9053\u5171\u7ebf\u30023.2\u516c\u91cc\u3001\u7d2f\u8ba1\u722c\u5347413\u7c73\u53ca1\u5c0f\u65f631\u5206\u949f\u4e0d\u542b\u8fd4\u7a0b\u3002","notes":"\u8f68\u8ff9\u4ece\u8f66\u7ad9\u5f00\u59cb\uff0c\u5e76\u975e\u57ce\u9547\u4e2d\u7684\u4efb\u610f\u4f4d\u7f6e\u3002\u672a\u6dfb\u52a0\u901a\u5f80\u5c71\u5cf0\u6807\u8bb0\u7684\u8fde\u63a5\u7ebf\u3002\u51fa\u53d1\u524d\u8bf7\u6838\u5b9e\u5929\u6c14\u53ca\u6797\u4e1a\u4f5c\u4e1a\u516c\u544a\uff1bGPX\u4e0d\u786e\u8ba4\u8def\u7ebf\u5f00\u653e\u6216\u5b89\u5168\u3002"}}}},{"kind":"poi","body":{"peak_slug":"stog-izerski","type_slug":"shelter","trail_id":null,"latitude":50.892497,"longitude":15.308775,"active":true,"source_url":"https://dolnoslaskie.szlaki.pttk.pl/2037-dolnoslaskie-schronisko-na-stogu-izerskim","last_verified_at":"2026-11-24T00:00:00Z","website_url":null,"google_maps_url":"https://www.google.com/maps?q=50.892497,15.308775","i18n":{"pl":{"name":"Schronisko na Stogu Izerskim","description":"Schronisko na zboczu Stogu Izerskiego, przy wybranym czerwonym szlaku przed jego ko\u0144cowym podej\u015bciem. PTTK opisuje budynek z lat 1922\u20131924 i widoki w stron\u0119 \u015awieradowa-Zdroju.","tips":"Przed wizyt\u0105 potwierd\u017a godziny, dost\u0119pne us\u0142ugi i ewentualny nocleg u gospodarza. Wpis nie potwierdza dost\u0119pno\u015bci miejsc ani dzia\u0142ania kolei gondolowej."},"en":{"name":"Schronisko na Stogu Izerskim \u2014 mountain hut","description":"Mountain hut on the slope of St\u00f3g Izerski, beside the selected red trail before its final ascent. PTTK describes the 1922\u20131924 building and views towards \u015awierad\u00f3w-Zdr\u00f3j.","tips":"Confirm opening hours, services and any overnight stay with the operator before visiting. This entry does not confirm vacancies or gondola operation."},"ua":{"name":"Schronisko na Stogu Izerskim \u2014 \u0433\u0456\u0440\u0441\u044c\u043a\u0438\u0439 \u043f\u0440\u0438\u0442\u0443\u043b\u043e\u043a","description":"\u0413\u0456\u0440\u0441\u044c\u043a\u0438\u0439 \u043f\u0440\u0438\u0442\u0443\u043b\u043e\u043a \u043d\u0430 \u0441\u0445\u0438\u043b\u0456 St\u00f3g Izerski \u0431\u0456\u043b\u044f \u043e\u0431\u0440\u0430\u043d\u043e\u0433\u043e \u0447\u0435\u0440\u0432\u043e\u043d\u043e\u0433\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443 \u043f\u0435\u0440\u0435\u0434 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u043b\u044c\u043d\u0438\u043c \u043f\u0456\u0434\u0439\u043e\u043c\u043e\u043c. PTTK \u043e\u043f\u0438\u0441\u0443\u0454 \u0431\u0443\u0434\u0456\u0432\u043b\u044e 1922\u20131924 \u0440\u043e\u043a\u0456\u0432 \u0456 \u043a\u0440\u0430\u0454\u0432\u0438\u0434\u0438 \u0432 \u0431\u0456\u043a \u015awierad\u00f3w-Zdr\u00f3j.","tips":"\u041f\u0435\u0440\u0435\u0434 \u0432\u0456\u0437\u0438\u0442\u043e\u043c \u0443\u0442\u043e\u0447\u043d\u0456\u0442\u044c \u0443 \u0433\u043e\u0441\u043f\u043e\u0434\u0430\u0440\u044f \u0433\u043e\u0434\u0438\u043d\u0438 \u0440\u043e\u0431\u043e\u0442\u0438, \u043f\u043e\u0441\u043b\u0443\u0433\u0438 \u0439 \u043c\u043e\u0436\u043b\u0438\u0432\u0456\u0441\u0442\u044c \u043d\u043e\u0447\u0456\u0432\u043b\u0456. \u0417\u0430\u043f\u0438\u0441 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0432\u0456\u043b\u044c\u043d\u0438\u0445 \u043c\u0456\u0441\u0446\u044c \u0447\u0438 \u0440\u043e\u0431\u043e\u0442\u0438 \u0433\u043e\u043d\u0434\u043e\u043b\u044c\u043d\u043e\u0457 \u0434\u043e\u0440\u043e\u0433\u0438."},"zh":{"name":"Schronisko na Stogu Izerskim\u2014\u2014\u5c71\u5c4b","description":"\u4f4d\u4e8eSt\u00f3g Izerski\u5c71\u5761\u4e0a\uff0c\u9760\u8fd1\u6240\u9009\u7ea2\u8272\u6b65\u9053\u7684\u6700\u540e\u4e0a\u5761\u6bb5\u4e4b\u524d\u3002PTTK\u4ecb\u7ecd\u4e86\u8fd9\u5ea7\u5efa\u4e8e1922\u81f31924\u5e74\u7684\u5efa\u7b51\u53ca\u671d\u5411\u015awierad\u00f3w-Zdr\u00f3j\u7684\u666f\u89c2\u3002","tips":"\u5230\u8bbf\u524d\u8bf7\u5411\u7ecf\u8425\u8005\u786e\u8ba4\u5f00\u653e\u65f6\u95f4\u3001\u670d\u52a1\u53ca\u4f4f\u5bbf\u5b89\u6392\u3002\u672c\u6761\u76ee\u4e0d\u786e\u8ba4\u7a7a\u623f\u6216\u7f06\u8f66\u8fd0\u884c\u60c5\u51b5\u3002"}}}},{"kind":"poi","body":{"peak_slug":"wysoki-kamien","type_slug":"shelter","trail_id":null,"latitude":50.845549,"longitude":15.491588,"active":true,"source_url":"https://dolnoslaskie.szlaki.pttk.pl/2033-dolnoslaskie-wysoki-kamien-schronisko","last_verified_at":"2026-11-24T00:00:00Z","website_url":null,"google_maps_url":"https://www.google.com/maps?q=50.845549,15.491588","i18n":{"pl":{"name":"Wysoki Kamie\u0144 \u2014 rejon schroniska i ska\u0142","description":"Rejon prywatnego schroniska przy ska\u0142ach Wysokiego Kamienia, opisany w katalogu PTTK. Punkt orientacyjny le\u017cy przy ko\u0144cu wybranego podej\u015bcia ze Szklarskiej Por\u0119by.","tips":"Pozycja oznacza rejon obiektu, nie jego wej\u015bcie. Potwierd\u017a aktualne godziny i us\u0142ugi przed wizyt\u0105; nie potwierdzono nocleg\u00f3w, cen ani dost\u0119pu do wie\u017cy."},"en":{"name":"Wysoki Kamie\u0144 \u2014 hut and rocks area","description":"Area of the private hut beside the rocks of Wysoki Kamie\u0144, described in the PTTK catalogue. This landmark is near the end of the selected ascent from Szklarska Por\u0119ba.","tips":"The position marks the facility area, not its entrance. Confirm current hours and services before visiting; accommodation, prices and tower access are unverified."},"ua":{"name":"Wysoki Kamie\u0144 \u2014 \u0440\u0430\u0439\u043e\u043d \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u0443 \u0442\u0430 \u0441\u043a\u0435\u043b\u044c","description":"\u0420\u0430\u0439\u043e\u043d \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0433\u043e \u043f\u0440\u0438\u0442\u0443\u043b\u043a\u0443 \u0431\u0456\u043b\u044f \u0441\u043a\u0435\u043b\u044c Wysoki Kamie\u0144, \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0439 \u0443 \u043a\u0430\u0442\u0430\u043b\u043e\u0437\u0456 PTTK. \u041e\u0440\u0456\u0454\u043d\u0442\u0438\u0440 \u0440\u043e\u0437\u0442\u0430\u0448\u043e\u0432\u0430\u043d\u0438\u0439 \u0431\u0456\u043b\u044f \u043a\u0456\u043d\u0446\u044f \u043e\u0431\u0440\u0430\u043d\u043e\u0433\u043e \u043f\u0456\u0434\u0439\u043e\u043c\u0443 \u0437\u0456 Szklarska Por\u0119ba.","tips":"\u041f\u043e\u0437\u043d\u0430\u0447\u043a\u0430 \u0432\u043a\u0430\u0437\u0443\u0454 \u0440\u0430\u0439\u043e\u043d \u043e\u0431\u2019\u0454\u043a\u0442\u0430, \u0430 \u043d\u0435 \u0439\u043e\u0433\u043e \u0432\u0445\u0456\u0434. \u041f\u0435\u0440\u0435\u0434 \u0432\u0456\u0437\u0438\u0442\u043e\u043c \u0443\u0442\u043e\u0447\u043d\u0456\u0442\u044c \u0433\u043e\u0434\u0438\u043d\u0438 \u0439 \u043f\u043e\u0441\u043b\u0443\u0433\u0438; \u043d\u043e\u0447\u0456\u0432\u043b\u044f, \u0446\u0456\u043d\u0438 \u0442\u0430 \u0434\u043e\u0441\u0442\u0443\u043f \u0434\u043e \u0432\u0435\u0436\u0456 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u0456."},"zh":{"name":"Wysoki Kamie\u0144\u2014\u2014\u5c71\u5c4b\u53ca\u5ca9\u77f3\u533a\u57df","description":"PTTK\u76ee\u5f55\u4ecb\u7ecd\u7684Wysoki Kamie\u0144\u5ca9\u77f3\u65c1\u79c1\u4eba\u5c71\u5c4b\u533a\u57df\u3002\u6b64\u5730\u6807\u4f4d\u4e8e\u6240\u9009Szklarska Por\u0119ba\u4e0a\u5c71\u8def\u7ebf\u7684\u7ec8\u70b9\u9644\u8fd1\u3002","tips":"\u6807\u8bb0\u8868\u793a\u8bbe\u65bd\u6240\u5728\u533a\u57df\uff0c\u5e76\u975e\u5165\u53e3\u3002\u5230\u8bbf\u524d\u8bf7\u786e\u8ba4\u6700\u65b0\u5f00\u653e\u65f6\u95f4\u548c\u670d\u52a1\uff1b\u4f4f\u5bbf\u3001\u4ef7\u683c\u53ca\u89c2\u666f\u5854\u901a\u884c\u60c5\u51b5\u672a\u7ecf\u6838\u5b9e\u3002"}}}}],"ranges":[{"id":3,"slug":"gory-izerskie"}]}$manifest$::jsonb m),
expected as (select p, (select r->'body' from jsonb_array_elements(m->'records') r where r->>'kind'='trail' and r->'body'->>'peak_slug'=p->>'slug') tb,
 (select r->'body' from jsonb_array_elements(m->'records') r where r->>'kind'='poi' and r->'body'->>'peak_slug'=p->>'slug') pb
 from manifest,jsonb_array_elements(m->'peaks') p)
select e.p->>'slug' peak_slug, mr.slug range_slug,
 (select count(*) from public.trails where peak_id=p.id and active) trails,
 (select count(*) from public.pois where peak_id=p.id and active) pois,
 case when t.route_geometry is not null then 1 else 0 end mapped_trails,
 (select array_agg(lang order by lang collate "C") from public.trails_i18n where trail_id=t.id) trail_languages,
 (select array_agg(lang order by lang collate "C") from public.pois_i18n where poi_id=poi.id) poi_languages,
 coalesce((select jsonb_object_agg(k,to_jsonb(p)->k) from jsonb_object_keys(e.p) k)=e.p
 and mr.slug=(select r->>'slug' from manifest,jsonb_array_elements(m->'ranges') r where (r->>'id')::bigint=p.range_id)
 and not exists(select from unnest(array['peak_id','slug','start_point_name','end_point_name','distance_km','elevation_gain_m','time_min','difficulty','route_type','active','source_url','last_verified_at','map_url','gpx_url','distance_source_url','distance_verified_at','elevation_gain_source_url','elevation_gain_verified_at','time_source_url','time_verified_at','route_geometry','geometry_source_url','geometry_verified_at']) k where to_jsonb(t)->k is distinct from to_jsonb(jsonb_populate_record(null::public.trails,e.tb||jsonb_build_object('peak_id',p.id)))->k)
 and not exists(select from unnest(array['peak_id','trail_id','type_id','latitude','longitude','active','source_url','last_verified_at','website_url','google_maps_url']) k where to_jsonb(poi)->k is distinct from to_jsonb(jsonb_populate_record(null::public.pois,e.pb||jsonb_build_object('peak_id',p.id,'type_id',ty.id)))->k)
 and (select jsonb_object_agg(lang,jsonb_build_object('name',name,'description',description,'notes',notes)) from public.trails_i18n where trail_id=t.id)=e.tb->'i18n'
 and (select jsonb_object_agg(lang,jsonb_build_object('name',name,'description',description,'tips',tips)) from public.pois_i18n where poi_id=poi.id)=e.pb->'i18n',false) review_matches,
 exists(select from peakguide_private.catalogue_batch_receipts where batch_key='nonkgp-05' and snapshot->>'manifest_sha256'='965419a3686a78ee31b4f26a3cd5d4f535856646e0a4558a12a08a7c90213e14' and snapshot->>'version'='1') package_applied
from expected e left join public.peaks p on p.id=(e.p->>'id')::bigint and p.slug=e.p->>'slug'
left join public.mountain_ranges mr on mr.id=p.range_id
left join public.trails t on t.peak_id=p.id and t.slug=e.tb->>'slug'
left join public.poi_types ty on ty.slug=e.pb->>'type_slug'
left join public.pois poi on poi.peak_id=p.id and poi.source_url=e.pb->>'source_url' and poi.type_id=ty.id
order by e.p->>'slug';
